Repair and extend the SCAMP-Trie CPU pipeline in `/workspace/src`.
Make live prefix updates, compact memory snapshots, and reloaded lookup agree.
Support full 128-bit IPv6 longest prefix matching with last-write-wins puts.
A loaded image is independent of later live updates and other saved images.
Validate an entire packed image before replacing the loaded state.
Preserve the half/full node, NI bitmap, fallback, and bulk-child invariants.
Use `/workspace/PROTOCOL.md` for complete operations, bit layouts and bounds.
The supplied C++ core, exporter, entry point, and new image API are editable.
Only the complete `src/` tree is collected: regular UTF-8 files within its bounds.
The fixed Python front end and offline GNU C++ toolchain are supplied.
Build with `cd /workspace && python3 build.py` as the non-root workspace user.
The public CLI is `python3 run.py`: one JSON request and response per process.
Run `python3 public_check.py` for bounded, non-root public sanity checks.
Those examples are small; implement every documented case and boundary.
This is a CPU storage/lookup model; FPGA timing and packet rates are outside scope.
"""Build the collected C++ tree with the supplied offline compiler, as non-root."""
import argparse,hashlib,json,os,shutil,stat,subprocess,sys,tarfile,tempfile
from pathlib import Path
HERE=Path(__file__).resolve().parent
TOOLCHAIN_SHA256='c36158f4c5f6be0211c30ba58a15c94c32165aa3be92f36e7cbe2e654d811dc4'

def signature(st):return(st.st_dev,st.st_ino,st.st_mode,st.st_size,st.st_mtime_ns,st.st_ctime_ns,st.st_nlink)
def collect(source,target):
 source=Path(source);target=Path(target);target.mkdir()
 if source.is_symlink()or not source.is_dir():raise ValueError('src must be a directory')
 total=0;seen={};files=[]
 for base,dirs,names in os.walk(source,followlinks=False):
  rel=Path(base).relative_to(source)
  for name in sorted(dirs+names):
   p=Path(base)/name;r=rel/name;st=p.lstat();seen[str(r)]=signature(st)
   if len(seen)>128:raise ValueError('src entry bound')
   q=target/r
   if stat.S_ISDIR(st.st_mode):q.mkdir();continue
   if not stat.S_ISREG(st.st_mode)or st.st_nlink!=1:raise ValueError('src requires regular unlinked files')
   total+=st.st_size
   if total>4*1024**2:raise ValueError('src byte bound')
   fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
   try:
    if signature(os.fstat(fd))!=signature(st):raise ValueError('source changed')
    with os.fdopen(fd,'rb',closefd=False)as f:raw=f.read(st.st_size+1)
    if len(raw)!=st.st_size or signature(os.fstat(fd))!=signature(st):raise ValueError('source changed')
   finally:os.close(fd)
   raw.decode('utf-8');q.write_bytes(raw)
   if p.suffix=='.cpp':files.append(str(r))
 after={}
 for base,dirs,names in os.walk(source,followlinks=False):
  for name in dirs+names:
   p=Path(base)/name;after[str(p.relative_to(source))]=signature(p.lstat())
 if after!=seen:raise ValueError('source changed during collection')
 if not files:raise ValueError('no .cpp source')
 return sorted(files)

def install_toolchain(destination):
 archive=HERE/'toolchain/toolchain.tar.gz'
 if archive.stat().st_size>64*1024**2:raise ValueError('toolchain archive size')
 if hashlib.sha256(archive.read_bytes()).hexdigest()!=TOOLCHAIN_SHA256:raise ValueError('fixed toolchain checksum')
 destination.mkdir()
 with tarfile.open(archive,'r:gz')as t:
  members=t.getmembers()
  if len(members)>4096 or sum(x.size for x in members)>128*1024**2:raise ValueError('toolchain bounds')
  for m in members:
   parts=Path(m.name).parts
   if not m.isfile()or parts[:2]!=('opt','scamp-toolchain')or '..'in parts or m.size>64*1024**2:raise ValueError('toolchain member')
   p=destination.joinpath(*parts[2:]);p.parent.mkdir(parents=True,exist_ok=True)
   with t.extractfile(m)as src,p.open('xb')as dst:shutil.copyfileobj(src,dst)
   p.chmod(0o555 if m.mode&0o111 else 0o444)
 return destination/'cxx.py'

def main():
 if os.geteuid()==0:raise ValueError('build requires non-root execution')
 parser=argparse.ArgumentParser();parser.add_argument('--source',type=Path,default=HERE/'src');parser.add_argument('--output',type=Path,default=HERE/'tmp/scamptrie');args=parser.parse_args()
 scratch=HERE/'tmp';scratch.mkdir(exist_ok=True);args.output.parent.mkdir(parents=True,exist_ok=True)
 with tempfile.TemporaryDirectory(prefix='native-build-',dir=scratch)as name:
  folder=Path(name);frozen=folder/'src';files=collect(args.source,frozen);compiler=install_toolchain(folder/'compiler')
  output=folder/'program';env=dict(os.environ,TMPDIR=str(folder),OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1')
  argv=[sys.executable,str(compiler),'-std=c++14','-O2','-Wno-format','-static-libstdc++','-static-libgcc','-I'+str(frozen),*[str(frozen/p)for p in files],'-o',str(output)]
  result=subprocess.run(argv,env=env)
  if result.returncode:return result.returncode or 1
  st=output.lstat()
  if not stat.S_ISREG(st.st_mode)or st.st_nlink!=1 or st.st_size>64*1024**2:raise ValueError('compiled program shape')
  fd,name=tempfile.mkstemp(prefix='scamp-program-',dir=args.output.parent);os.close(fd)
  staged=Path(name);shutil.copyfile(output,staged);staged.chmod(0o555);os.replace(staged,args.output)
 print('Build complete.',flush=True);return 0
if __name__=='__main__':
 try:sys.exit(main())
 except (ValueError,OSError,UnicodeError)as exc:print('BUILD FAIL:',exc,file=sys.stderr);sys.exit(1)

"""Fixed JSON-to-native input adapter: syntax/bounds only, no lookup/image evaluator."""
import json,os,re,sys
from pathlib import Path
MAX_INPUT=32*1024**2
HEX=re.compile(r'[0-9a-f]+\Z')
def number(v,lo,hi):return type(v)is int and lo<=v<=hi
def keys(v,names):
 if type(v)is not dict or set(v)!=set(names.split()):raise ValueError('fields')
def hx(v,n):
 if type(v)is not str or len(v)!=n or not HEX.fullmatch(v):raise ValueError('hex')
 return v
def pairs(items):
 out={}
 for k,v in items:
  if k in out:raise ValueError('duplicate key')
  out[k]=v
 return out
def parse(raw):
 if len(raw)>MAX_INPUT:raise ValueError('input bytes')
 v=json.loads(raw.decode('utf-8'),object_pairs_hook=pairs,parse_constant=lambda x:(_ for _ in()).throw(ValueError(x)))
 keys(v,'cases');cases=v['cases']
 if type(cases)is not list or not 1<=len(cases)<=2:raise ValueError('cases')
 lines=[str(len(cases))]
 def ip(a):
  a=hx(a,32);lines.extend([a[:16],a[16:]])
 def loc(a):
  if type(a)is not list or len(a)!=2 or not number(a[0],0,10) or not number(a[1],0,131071):raise ValueError('locator')
  lines.extend(map(str,a))
 def image(d):
  keys(d,'root front16 front64 cells banks bitmaps nexthops')
  if d['root']is None:lines.extend(['-1','0'])
  else:loc(d['root'])
  for field,width in [('front16',4),('front64',16)]:
   entries=d[field]
   if type(entries)is not list or len(entries)>4096:raise ValueError('front shape')
   lines.append(str(len(entries)))
   for e in entries:
    if type(e)is not list or len(e)!=3:raise ValueError('front entry')
    lines.append(hx(e[0],width));loc(e[1:])
  cells=d['cells'];banks=d['banks']
  if type(cells)is not list or len(cells)!=11 or not all(number(x,0,131072)for x in cells):raise ValueError('cells')
  if type(banks)is not list or len(banks)!=11:raise ValueError('banks')
  lines.extend(map(str,cells));total=0
  for bank in banks:
   if type(bank)is not list or len(bank)>65536:raise ValueError('bank')
   total+=len(bank);lines.append(str(len(bank)))
   for word in bank:lines.append(hx(word,64))
  if total>65536:raise ValueError('rows bound')
  for field,limit in [('bitmaps',8193),('nexthops',8192)]:
   a=d[field]
   if type(a)is not list or len(a)>limit:raise ValueError('side RAM')
   lines.append(str(len(a)))
   for x in a:
    if field=='bitmaps':lines.append(hx(x,16))
    else:
     if not number(x,0,4194302):raise ValueError('NI')
     lines.append(str(x))
 for case in cases:
  keys(case,'ops');ops=case['ops']
  if type(ops)is not list or len(ops)>133120:raise ValueError('operation count')
  lines.append(str(len(ops)));routes=set();fronts=[set(),set()];puts=queries=saves=loads=0
  for op in ops:
   if type(op)is not list or not op or type(op[0])is not str:raise ValueError('operation')
   name=op[0]
   if name=='put' and len(op)==4:
    a=hx(op[1],32);length=op[2];hop=op[3]
    if not number(length,0,128) or not number(hop,0,4194302):raise ValueError('route fields')
    p=int(a,16)>>(128-length)<<(128-length);routes.add((p,length))
    if 16<length<=64:fronts[0].add(p>>112)
    elif length>64:fronts[1].add(p>>64)
    puts+=1;lines.append('P');ip(a);lines.extend([str(length),str(hop)])
   elif name in ('query','image_query') and len(op)==2:
    a=op[1]
    if type(a)is not list:raise ValueError('queries')
    queries+=len(a);lines.extend(['Q'if name=='query'else'I',str(len(a))])
    for address in a:ip(address)
   elif name=='save' and len(op)==1:saves+=1;lines.append('S')
   elif name=='load_saved' and len(op)==2:
    if not number(op[1],0,saves-1):raise ValueError('saved index')
    loads+=1;lines.extend(['R',str(op[1])])
   elif name=='load' and len(op)==2:loads+=1;lines.append('L');image(op[1])
   else:raise ValueError('opcode')
   if len(routes)>8192 or puts>131072 or queries>131072 or saves>3 or loads>16 or any(len(f)>4096 for f in fronts):raise ValueError('case bounds')
 return ('\n'.join(lines)+'\n').encode('ascii')
def main():
 try:wire=parse(sys.stdin.buffer.read(MAX_INPUT+1))
 except (ValueError,AssertionError,TypeError,UnicodeError,RecursionError):
  print('{"error":"invalid"}');return
 binary=os.environ.get('SCAMP_BINARY',str(Path(__file__).resolve().parent/'tmp/scamptrie'))
 r,w=os.pipe();pid=os.fork()
 if pid==0:
  os.close(r)
  try:
   while wire:
    n=os.write(w,wire);wire=wire[n:]
   os.close(w);os._exit(0)
  except BaseException:os._exit(1)
 os.close(w);os.dup2(r,0);os.close(r)
 os.environ['SCAMP_FEED_PID']=str(pid)
 os.execv(binary,[binary])
if __name__=='__main__':main()

#ifndef __SCAMPTRIE_BASE_H__
#define __SCAMPTRIE_BASE_H__

#include <cstdint>

typedef uint64_t nexthop_t;
static constexpr nexthop_t LPM_INVALID_NH = static_cast<nexthop_t>(-1);

struct ip6_t {
    uint64_t hi;
    uint64_t lo;
};

#define SCAMPTRIE_OK 0
#define SCAMPTRIE_FAIL 1

// First level bits configuration (default: 18)
#ifndef FIRST_LEVEL_BITS
#define FIRST_LEVEL_BITS 16
#endif

// mask for the bigendian FIRST_LEVEL_BITS bits
#define MASK_FIRST_LEVEL (((~0ULL) << (64 - FIRST_LEVEL_BITS)) & 0xFFFFFFFFFFFFFFFFULL)
// Keep MASK18 for backward compatibility, but it's now based on FIRST_LEVEL_BITS

#define RAM_NUM 11
#define STAGE_NUM 22
#define STAGE_NONE 60       // stage for Invalid Child
#define STAGE_DEFAULT 59    // stage for child which have not been assigned a stage
#define MAX_FIB_NUM 15

#define MEGA_BYTES (1024 * 1024)
#define KILO_BYTES (1024)
#define BYTES_128b (16)
#define BYTES_256b (32)
constexpr uint32_t NODE_SPACE[6] = {
    0,
    BYTES_128b,
    BYTES_256b,
    BYTES_256b,
    BYTES_128b,
    BYTES_256b
};

// Function declarations
void msg_error(const char* msg);
void msg_warn(const char* msg);
void msg_info(const char* msg);

// equal for first 'len' bits
// check a64[:len] == b64[:len]
bool is_prefix_equal(const uint64_t a64, const uint64_t b64, const uint8_t len);

// equal for first 'len' bits
// check a128[:len] == b128[:len]
bool is_prefix_equal(const ip6_t& a, const ip6_t& b, const uint8_t len);

// count the number of '1' in the bitmap[0,pos)
uint16_t count_ones_before_pos(uint64_t bitmap, uint16_t pos);

uint8_t round_to_6(uint8_t len);

/// @brief prefix in subtrie node
/// @param prefix the prefix (64 bits)
/// @param len the length of the prefix
/// @return prefix in subtrie node (< 6 bits)
/// @note sample: prefix=(xxxxxx)(110101)(xxxxxx)..., len=9 -> return 110101
uint16_t get_substring_in_subtrie(uint64_t prefix, uint8_t len);

/// @brief prefix in subtrie node
/// @param prefix the prefix (128 bits)
/// @param len the length of the prefix
/// @return prefix in subtrie node (< 6 bits)
/// @note sample: prefix=(xxxxxx)(110101)(xxxxxx)(xxxxxx)..., len=9 -> return 110101
uint16_t get_substring_in_subtrie(const ip6_t& prefix, const uint8_t len);

/// @brief nexthop bitmap position for the prefix (|prefix| = 6, len < 6)
/// @param prefix the prefix (6 bits)
/// @param len extract the first len bits (< 6)
/// @return nexthop bitmap position
/// @note sample: prefix=(110101), len=3 -> return (1|110) = 14
uint16_t get_nh_bitmap_pos_6(const uint16_t prefix, const uint8_t len);

/// @brief nexthop bitmap position for the prefix (|prefix| = 64, len < 64)
/// @param prefix the prefix (64 bits)
/// @param len extract the first len bits (< 64)
/// @return nexthop bitmap position
/// @note prefix = (xxxxxx)(110101)(xxxxxx)..., len = 6k+3 -> return (1|110) = 14
uint16_t get_nh_bitmap_pos_64(const uint64_t prefix, const uint8_t len);

/// @brief nexthop bitmap position for the prefix (|prefix| = 128, len < 128)
/// @param prefix the prefix (128 bits)
/// @param len extract the first len bits (< 128)
/// @return nexthop bitmap position
/// @note sample: prefix=(xxxxxx)(110101)(xxxxxx)(xxxxxx)..., len=9 -> return (1|110) = 14
uint16_t get_nh_bitmap_pos_128(const ip6_t& prefix, const uint8_t len);

/// @brief mask the address with the length
/// @param address the address to mask
/// @param len the length to mask
/// @note ip = 0x1234567890ABCDEF.0/12 -> 0x1230000000000000.0/12
void mask_address(ip6_t& address, uint8_t len);

/// @brief check if A is a prefix of B
/// @return true if A is a prefix of B, false otherwise
bool is_A_prefix_of_B(const ip6_t& A, const uint8_t A_len, const ip6_t& B, const uint8_t B_len);

typedef uint8_t stage_t;

void getmax_stage(stage_t &stage1, stage_t stage2);

inline stage_t higher_stage(stage_t stage) {
    return stage == STAGE_DEFAULT ? (stage_t)0 : stage + 1;
}

inline stage_t lower_stage(stage_t stage) {
    return stage == 0 ? STAGE_DEFAULT : stage - 1;
}

enum ScampNodeType : unsigned int {
    NONE = 0,
    TYPE1 = 1, // 2 children
    TYPE2,     // 6 children
    TYPE3,     // bitmap + pointer (>= 7 children)
    TYPE4,     // 1 prefix
    TYPE5      // 2 prefixes
};

// 6 + 4 + 22 = 32 bits
struct ChildInfo {
    uint8_t ip_sub6; // 6 bits
    stage_t stageID; // 4 bits
    uint32_t childPointer; // 22 bits
    ChildInfo(): stageID(STAGE_NONE), childPointer(UINT32_MAX) {}
    bool operator<(const ChildInfo& other) const {
        return ip_sub6 < other.ip_sub6;
    }
};

// stored out of 11 stages
struct RootInfo {
    stage_t stageID;
    uint32_t rootPointer;
    RootInfo(): stageID(STAGE_NONE), rootPointer(UINT32_MAX) {}
};

//prefix info
// 64 + 8 + 22 = 94 bits
struct PrefixInfo {
    uint64_t ip_64;
    uint8_t len_64;
    uint32_t nexthop; // 22 bits
    uint32_t bmp_entry_idx;
    ip6_t ip_128;
    uint8_t len_128;
    uint16_t get_nh_bitmap_pos() {
        return ::get_nh_bitmap_pos_64(ip_64, len_64);
    }
    bool operator<(const PrefixInfo& other) const {
        return get_nh_bitmap_pos_64(ip_64, len_64) < get_nh_bitmap_pos_64(other.ip_64, other.len_64);
    }
    bool match64(uint64_t ip64) { return is_prefix_equal(ip64, ip_64, len_64); }
    bool match128(const ip6_t& ip) { return is_prefix_equal(ip, ip_128, len_128); }
};

// base scamptrie node
// 1 + 2 + 22 = 25 bits
struct ScampTrieNode {
    ScampTrieNode() {nodeType = NONE; child_highest = STAGE_DEFAULT;}
    virtual ~ScampTrieNode() = default;

    ScampNodeType nodeType; // 3 bits
    // bmp refers to an index in BMPManager when enable DYNAMIC
    ip6_t ip_128;
    uint8_t len_128;
    uint8_t depth;
    uint32_t bmp; // 22 bits
    stage_t cur_stage;
    stage_t child_highest; // among its children
    uint32_t topo_export_idx; // used for topo export (only for debug)
    uint32_t mem_addr; // the real address on hardware memory (at each layer)

    /// Only Type1/Type2/Type3 have nhBitmapPointer; base/Type4/Type5 return a static dummy (must not be used for write).
    virtual uint16_t& get_nh_bitmap_pointer() {
        static uint16_t dummy = 0;
        msg_error("ScampTrieNode::get_nh_bitmap_pointer: not implemented for this node type");
        return dummy;
    }
    virtual uint32_t& get_nh_pointer() {
        msg_error("ScampTrieNode::get_nh_pointer: not implemented");
        return bmp; // just for compiler
    }
};

// Type 1: 2 children
// (25) + 16 + 22 + 2 * 32 + 1 = 128 bits
struct ScampTrieNode1 : public ScampTrieNode {
    ScampTrieNode1() {nodeType = TYPE1;}
    ~ScampTrieNode1() = default;

    uint16_t nhBitmapPointer;
    uint32_t nhPointer; // 22 bits
    ChildInfo childInfo[2];
    uint8_t reserved; // 1 bit

    uint16_t& get_nh_bitmap_pointer() override { return nhBitmapPointer; }
    uint32_t& get_nh_pointer() override { return nhPointer; }
};

/// @brief  Type 2: 6 children
/// (25) + 16 + 22 + 6 * 32 + 1 = 256 bits
struct ScampTrieNode2 : public ScampTrieNode {
    ScampTrieNode2() {nodeType = TYPE2;}
    ~ScampTrieNode2() = default;

    uint16_t nhBitmapPointer;
    uint32_t nhPointer; // 22 bits
    ChildInfo childInfo[6];
    uint8_t reserved; // 1 bit

    uint16_t& get_nh_bitmap_pointer() override { return nhBitmapPointer; }
    uint32_t& get_nh_pointer() override { return nhPointer; }
};

/// @brief Type 3: bitmap + pointer (>= 7 children)
/// (25) + 16 + 22 + 64 + 22 + 5 + 102 = 256 bits
struct ScampTrieNode3 : public ScampTrieNode {
    ScampTrieNode3() {nodeType = TYPE3;}
    ~ScampTrieNode3() = default;

    uint16_t nhBitmapPointer;
    uint32_t nhPointer; // 22 bits
    uint64_t childBitmap;
    uint32_t childPointer; // 22 bits
    stage_t childStage; // 5 bits
    ChildInfo freeChild[3]; // 3 * 32 = 96 bits
    // uint64_t reserved1;
    // uint64_t reserved2; // 64 + 38 = 102 bits

    uint16_t& get_nh_bitmap_pointer() override { return nhBitmapPointer; }
    uint32_t& get_nh_pointer() override { return nhPointer; }
};

/// @brief Type 4: 1 prefix
/// (25) + 16 + 22 + 94 + 9 = 128
struct ScampTrieNode4 : public ScampTrieNode {
    ScampTrieNode4() {nodeType = TYPE4;}
    ~ScampTrieNode4() = default;

    PrefixInfo prefixInfo[1]; // 94 bits
    uint16_t reserved; // 9 bits
};

// TRIE_NODE_5
// (25) + 16 + 22 + 2 * 94 + 43 = 256 bits
struct ScampTrieNode5 : public ScampTrieNode {
    ScampTrieNode5() {nodeType = TYPE5;}
    ~ScampTrieNode5() = default;

    PrefixInfo prefixInfo[2]; // 188 bits
    uint64_t reserved; // 64 + 43 = 107 bits
};

#endif // __SCAMPTRIE_BASE_H__
#include "scamptrie_base.h"
#include <cstdio>
#include <cstdlib>

void msg_error(const char* msg) {
    printf("[ERROR] %s\n", msg);
    exit(1);
}

void msg_warn(const char* msg) {
    printf("[WARN] %s\n", msg);
}

void msg_info(const char* msg) {
    printf("[INFO] %s\n", msg);
}

uint8_t round_to_6(uint8_t len) {
    return (len / 6) * 6;
}

// equal for first 'len' bits
bool is_prefix_equal(const uint64_t a64, const uint64_t b64, const uint8_t len) {
    uint64_t mask = len == 0 ? 0 : (~0ULL) << (64 - len);
    return (a64 & mask) == (b64 & mask);
}

bool is_prefix_equal(const ip6_t& a, const ip6_t& b, const uint8_t len) {
    if (len <= 64) return is_prefix_equal(a.hi, b.hi, len);
    return a.hi == b.hi && is_prefix_equal(a.lo, b.lo, len - 64);
}

uint16_t count_ones_before_pos(uint64_t bitmap, uint16_t pos) {
    if (pos == 0) return 0;
    if (pos >= 64) return __builtin_popcountll(bitmap);
    uint64_t mask = (1ULL << pos) - 1;
    return (uint16_t)__builtin_popcountll(bitmap & mask);
}

uint16_t get_substring_in_subtrie(uint64_t prefix, uint8_t len) {
    if (len >= 60) {
        return (uint16_t)(prefix & 0xf) << 2; // mask bit[61-64], then fill 2 0s
    }
    uint8_t subtrie_base_len = len / 6 * 6 + 6; // 0~5->6, 6~11->12, ...
    return (uint16_t)((prefix >> (64 - subtrie_base_len)) & 0x3F);
}

uint16_t get_substring_in_subtrie(const ip6_t& prefix, const uint8_t len) {
    if (len < 60) return get_substring_in_subtrie(prefix.hi, len);
    if (len >= 66) return get_substring_in_subtrie(prefix.lo << 2, len - 66);
    return ((prefix.hi & 0xf) << 2) | (prefix.lo >> 62);
}

uint16_t get_nh_bitmap_pos_6(const uint16_t prefix, const uint8_t len) {
    return (1ull << len) + (prefix >> (6 - len));
}

uint16_t get_nh_bitmap_pos_64(const uint64_t prefix, const uint8_t len) {
    return get_nh_bitmap_pos_6(get_substring_in_subtrie(prefix, len), len % 6);
}

uint16_t get_nh_bitmap_pos_128(const ip6_t& prefix, const uint8_t len) {
    if (len < 60) return get_nh_bitmap_pos_64(prefix.hi, len);
    if (len >= 66) return get_nh_bitmap_pos_64(prefix.lo << 2, len - 66);
    return get_nh_bitmap_pos_6(get_substring_in_subtrie(prefix, len), len % 6);
}

void mask_address(ip6_t& address, uint8_t len) {
    if (len > 64) {
        address.lo >>= 128 - len;
        address.lo <<= 128 - len;
    } else {
        address.hi >>= 64 - len;
        address.hi <<= 64 - len;
        address.lo = 0;
    }
}

bool is_A_prefix_of_B(const ip6_t& A, const uint8_t A_len, const ip6_t& B, const uint8_t B_len) {
    if (A_len > B_len) return false;
    if (A_len <= 64) return is_prefix_equal(A.hi, B.hi, A_len);
    return A.hi == B.hi && is_prefix_equal(A.lo, B.lo, A_len - 64);
}

void getmax_stage(uint8_t &stage1, uint8_t stage2) {
    if (stage1 == STAGE_DEFAULT || stage1 < stage2) stage1 = stage2;
}

