#ifndef SCAMP_PREFIX_TRIE_H
#define SCAMP_PREFIX_TRIE_H

#include "core.h"
#include <vector>

// Binary trie over normalized prefixes used to compute global best-matching
// prefixes (BMP values) for image nodes.
class PrefixTrie {
public:
    PrefixTrie() { nodes_.push_back(Node()); }

    // Returns false when the exact normalized prefix is already present.
    bool insert(const ip6_t& a, int len, nexthop_t hop) {
        int cur = 0;
        for (int i = 0; i < len; ++i) {
            int b = ipbit(a, i);
            if (nodes_[cur].ch[b] < 0) {
                nodes_[cur].ch[b] = (int)nodes_.size();
                nodes_.push_back(Node());
            }
            cur = nodes_[cur].ch[b];
        }
        if (nodes_[cur].has) return false;
        nodes_[cur].has = true;
        nodes_[cur].hop = hop;
        return true;
    }

    // Longest stored prefix of length <= depth that matches the region whose
    // first `depth` bits are those of `region` (matches its entire region).
    // Returns false when no such prefix exists.
    bool bmp_for(const ip6_t& region, int depth, nexthop_t& out) const {
        bool found = nodes_[0].has;
        nexthop_t best = nodes_[0].hop;
        int cur = 0;
        for (int i = 0; i < depth; ++i) {
            int nx = nodes_[cur].ch[ipbit(region, i)];
            if (nx < 0) break;
            cur = nx;
            if (nodes_[cur].has) { found = true; best = nodes_[cur].hop; }
        }
        out = best;
        return found;
    }

private:
    struct Node {
        int ch[2];
        bool has;
        nexthop_t hop;
        Node() { ch[0] = ch[1] = -1; has = false; hop = 0; }
    };
    std::vector<Node> nodes_;
};

#endif
