// Live FIB: last-write-wins puts of normalized prefixes and longest prefix
// matching queries.  Every distinct normalized prefix is kept, even when it is
// redundant or shares its hop with another prefix.
class LiveFib {
public:
    void put(ip6_t addr, int len, nexthop_t hop);
    nexthop_t query(ip6_t addr) const;
    std::vector<RouteEntry> routes() const;

private:
    struct Key {
        uint64_t hi;
        uint64_t lo;
        int len;
        bool operator==(const Key& o) const {
            return len == o.len && hi == o.hi && lo == o.lo;
        }
    };
    struct KeyHash {
        size_t operator()(const Key& k) const {
            uint64_t h = k.hi * 0x9e3779b97f4a7c15ULL;
            h ^= k.lo + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
            h ^= (uint64_t)k.len * 0xc2b2ae3d27d4eb4fULL + (h << 6) + (h >> 2);
            return (size_t)h;
        }
    };
    std::unordered_map<Key, nexthop_t, KeyHash> map_;
};

#endif
