#include "capture.hpp"
#include "prefix_trie.h"

#include <algorithm>
#include <map>
#include <utility>
#include <vector>

namespace {

struct BPrefix {
    ip6_t addr;
    int len;
    nexthop_t hop;
};

struct BNode {
    int type;                 // 1..5
    int origin;
    int depth;
    int level;
    ip6_t region;
    std::vector<BPrefix> locals;
    std::vector<std::pair<uint64_t, BNode*> > kids; // sorted by key
    BPrefix inl[2];
    int inln;
    int stage;
    uint32_t cell;
    int slot;
    uint64_t bm;
    std::vector<nexthop_t> ni;
    int bmid;
    uint32_t nibase;
    uint32_t bmp;
    bool bulk;

    BNode() : type(0), origin(0), depth(0), level(0), inln(0), stage(-1), cell(0),
              slot(0), bm(0), bmid(-1), nibase(0), bmp(BMP_NULL), bulk(false) {
        region.hi = 0;
        region.lo = 0;
        inl[0].addr.hi = inl[0].addr.lo = 0;
        inl[0].len = 0;
        inl[0].hop = 0;
        inl[1] = inl[0];
    }
};

// Unique recursive decomposition: subtrees with one or two owned prefixes are
// TYPE4/TYPE5, larger subtrees are TYPE1/2/3 with local prefixes plus child
// subtrees partitioning the owned prefixes.
BNode* build_node(std::vector<BPrefix>& ps, int origin, int depth,
                  const ip6_t& region, int level) {
    BNode* n = new BNode();
    n->origin = origin;
    n->depth = depth;
    n->level = level;
    n->region = region;
    if (ps.size() == 1) {
        n->type = 4;
        n->inl[0] = ps[0];
        n->inln = 1;
        return n;
    }
    if (ps.size() == 2) {
        n->type = 5;
        n->inl[0] = ps[0];
        n->inl[1] = ps[1];
        n->inln = 2;
        return n;
    }
    std::map<uint64_t, std::vector<BPrefix> > groups;
    for (size_t i = 0; i < ps.size(); ++i) {
        const BPrefix& p = ps[i];
        if (p.len < depth + 6) {
            n->locals.push_back(p);       // relative lengths l = 0..5
        } else {
            groups[extract_bits(p.addr, depth, 6)].push_back(p);
        }
    }
    for (std::map<uint64_t, std::vector<BPrefix> >::iterator it = groups.begin();
         it != groups.end(); ++it) {
        ip6_t cr = region;
        set_bits(cr, depth, 6, it->first);
        BNode* ch = build_node(it->second, origin, depth + 6, cr, level + 1);
        n->kids.push_back(std::make_pair(it->first, ch));
    }
    size_t c = n->kids.size();
    n->type = c <= 2 ? 1 : (c <= 6 ? 2 : 3);
    return n;
}

void collect_bfs(const std::vector<BNode*>& roots, std::vector<BNode*>& out) {
    std::vector<BNode*> queue;
    for (size_t i = 0; i < roots.size(); ++i) queue.push_back(roots[i]);
    for (size_t h = 0; h < queue.size(); ++h) {
        BNode* n = queue[h];
        out.push_back(n);
        for (size_t j = 0; j < n->kids.size(); ++j) queue.push_back(n->kids[j].second);
    }
}

void destroy(BNode* n) {
    for (size_t j = 0; j < n->kids.size(); ++j) destroy(n->kids[j].second);
    delete n;
}

void pack_bits(std::bitset<256>& w, int& pos, uint64_t v, int n) {
    for (int i = 0; i < n; ++i) {
        w.set(pos++, ((v >> i) & 1) != 0);
    }
}

uint32_t pack_child(uint64_t key, int stage, uint32_t cell) {
    return (uint32_t)(key & 0x3F) | (uint32_t)(stage & 0xF) << 6 | cell << 10;
}

const uint32_t CHILD_ABSENT = 15u << 6;

uint64_t inline_frag(const BPrefix& p, int origin, int& len8) {
    if (origin == 0) {
        len8 = p.len;
        return p.addr.hi;
    }
    if (origin == FRONT16_BITS) {
        len8 = p.len - 16;
        return p.addr.hi << 16;
    }
    len8 = p.len - 64;
    return p.addr.lo;
}

} // namespace

ImageData capture_image(const std::vector<RouteEntry>& routes) {
    ImageData out;

    // ---- owner groups ----------------------------------------------------
    std::vector<BPrefix> g0;
    std::map<uint16_t, std::vector<BPrefix> > g16;
    std::map<uint64_t, std::vector<BPrefix> > g64;
    for (size_t i = 0; i < routes.size(); ++i) {
        BPrefix p;
        p.addr = routes[i].addr;
        p.len = routes[i].len;
        p.hop = routes[i].hop;
        if (p.len <= 16) g0.push_back(p);
        else if (p.len <= 64) g16[(uint16_t)(p.addr.hi >> 48)].push_back(p);
        else g64[p.addr.hi].push_back(p);
    }

    // ---- decomposition ---------------------------------------------------
    std::vector<BNode*> roots;
    BNode* root0 = 0;
    if (!g0.empty()) {
        ip6_t region;
        region.hi = 0;
        region.lo = 0;
        root0 = build_node(g0, 0, 0, region, 0);
        roots.push_back(root0);
    }
    std::vector<BNode*> r16, r64;
    for (std::map<uint16_t, std::vector<BPrefix> >::iterator it = g16.begin();
         it != g16.end(); ++it) {
        ip6_t region;
        region.hi = (uint64_t)it->first << 48;
        region.lo = 0;
        BNode* n = build_node(it->second, FRONT16_BITS, 16, region, 0);
        r16.push_back(n);
        roots.push_back(n);
    }
    for (std::map<uint64_t, std::vector<BPrefix> >::iterator it = g64.begin();
         it != g64.end(); ++it) {
        ip6_t region;
        region.hi = it->first;
        region.lo = 0;
        BNode* n = build_node(it->second, FRONT64_BITS, 64, region, 0);
        r64.push_back(n);
        roots.push_back(n);
    }

    std::vector<BNode*> nodes;
    collect_bfs(roots, nodes);

    // ---- stage assignment: every child stage strictly lower than its parent
    for (size_t i = 0; i < nodes.size(); ++i) {
        BNode* n = nodes[i];
        n->stage = MAX_STAGE - n->level;
    }

    // ---- TYPE3 direct/bulk split: at most three direct, the rest bulk ----
    for (size_t i = 0; i < nodes.size(); ++i) {
        BNode* n = nodes[i];
        if (n->type != 3) continue;
        for (size_t j = 0; j < n->kids.size(); ++j)
            n->kids[j].second->bulk = (j >= 3);
    }

    // ---- cell allocation per stage --------------------------------------
    std::vector<BNode*> byStage[RAM_NUM];
    for (size_t i = 0; i < nodes.size(); ++i) byStage[nodes[i]->stage].push_back(nodes[i]);

    for (int s = 0; s < RAM_NUM; ++s) {
        std::vector<std::vector<BNode*> > bulkGroups;
        std::vector<BNode*> half;   // two-cell ordinary nodes
        std::vector<BNode*> one;    // one-cell ordinary nodes
        for (size_t i = 0; i < nodes.size(); ++i) {
            BNode* p = nodes[i];
            if (p->type != 3) continue;
            std::vector<BNode*> g;
            for (size_t j = 0; j < p->kids.size(); ++j) {
                BNode* c = p->kids[j].second;
                if (c->bulk && c->stage == s) g.push_back(c);
            }
            if (!g.empty()) bulkGroups.push_back(g);
        }
        for (size_t i = 0; i < byStage[s].size(); ++i) {
            BNode* n = byStage[s][i];
            if (n->bulk) continue;
            if (n->type == 2 || n->type == 3 || n->type == 5) half.push_back(n);
            else one.push_back(n);
        }
        uint32_t next = 0;
        for (size_t g = 0; g < bulkGroups.size(); ++g) {
            // contiguous two-cell slots in increasing bulk-key order
            for (size_t i = 0; i < bulkGroups[g].size(); ++i) {
                bulkGroups[g][i]->cell = next + 2 * (uint32_t)i;
                bulkGroups[g][i]->slot = 2;
            }
            next += 2 * (uint32_t)bulkGroups[g].size();
        }
        for (size_t i = 0; i < half.size(); ++i) {
            half[i]->cell = next;
            half[i]->slot = 2;
            next += 2;
        }
        for (size_t i = 0; i < one.size(); ++i) {
            one[i]->cell = next;
            one[i]->slot = 1;
            next += 1;
        }
        out.cells[s] = next;
    }

    // ---- NI bitmaps, NI arrays, bitmap dictionary -----------------------
    uint32_t niTotal = 0;
    std::vector<uint64_t> pats;
    for (size_t i = 0; i < nodes.size(); ++i) {
        BNode* n = nodes[i];
        if (n->type > 3) continue;
        std::vector<std::pair<int, nexthop_t> > entries; // (position, hop)
        for (size_t j = 0; j < n->locals.size(); ++j) {
            const BPrefix& p = n->locals[j];
            int l = p.len - n->depth;
            uint64_t v = extract_bits(p.addr, n->depth, l);
            int pos = (1 << l) + (int)v;
            entries.push_back(std::make_pair(pos, p.hop));
        }
        std::sort(entries.begin(), entries.end());
        n->bm = 0;
        n->nibase = n->locals.empty() ? 0 : niTotal;
        for (size_t j = 0; j < entries.size(); ++j) {
            n->bm |= 1ULL << entries[j].first;
            n->ni.push_back(entries[j].second);
        }
        niTotal += (uint32_t)entries.size();
        pats.push_back(n->bm);
    }
    std::sort(pats.begin(), pats.end());
    pats.erase(std::unique(pats.begin(), pats.end()), pats.end());
    for (size_t i = 0; i < nodes.size(); ++i) {
        BNode* n = nodes[i];
        if (n->type > 3) continue;
        n->bmid = (int)(std::lower_bound(pats.begin(), pats.end(), n->bm) - pats.begin());
    }
    out.bitmaps = pats;
    out.nexthops.reserve(niTotal);
    for (size_t i = 0; i < nodes.size(); ++i) {
        BNode* n = nodes[i];
        for (size_t j = 0; j < n->ni.size(); ++j) out.nexthops.push_back(n->ni[j]);
    }

    // ---- global BMP values ----------------------------------------------
    {
        PrefixTrie trie;
        for (size_t i = 0; i < nodes.size(); ++i) {
            BNode* n = nodes[i];
            if (n->type <= 3) {
                for (size_t j = 0; j < n->locals.size(); ++j)
                    trie.insert(n->locals[j].addr, n->locals[j].len, n->locals[j].hop);
            } else {
                for (int j = 0; j < n->inln; ++j)
                    trie.insert(n->inl[j].addr, n->inl[j].len, n->inl[j].hop);
            }
        }
        for (size_t i = 0; i < nodes.size(); ++i) {
            BNode* n = nodes[i];
            nexthop_t want = 0;
            n->bmp = trie.bmp_for(n->region, n->depth, want) ? (uint32_t)want : BMP_NULL;
        }
    }

    // ---- pack records into banks ----------------------------------------
    for (int s = 0; s < RAM_NUM; ++s)
        out.banks[s].assign((out.cells[s] + 1) / 2, std::bitset<256>());

    for (size_t i = 0; i < nodes.size(); ++i) {
        BNode* n = nodes[i];
        std::bitset<256> rec;
        int pos = 0;
        pack_bits(rec, pos, (uint64_t)n->type, 3);
        pack_bits(rec, pos, (uint64_t)n->bmp, 22);
        if (n->type == 1 || n->type == 2) {
            pack_bits(rec, pos, (uint64_t)n->bmid, 16);
            pack_bits(rec, pos, (uint64_t)n->nibase, 22);
            int slots = (n->type == 1) ? 2 : 6;
            for (int j = 0; j < slots; ++j) {
                uint32_t rec32 = CHILD_ABSENT;
                if (j < (int)n->kids.size())
                    rec32 = pack_child(n->kids[j].first, n->kids[j].second->stage,
                                       n->kids[j].second->cell);
                pack_bits(rec, pos, rec32, 32);
            }
            pack_bits(rec, pos, 0, 1);
        } else if (n->type == 3) {
            pack_bits(rec, pos, (uint64_t)n->bmid, 16);
            pack_bits(rec, pos, (uint64_t)n->nibase, 22);
            uint64_t bulkBm = 0;
            for (size_t j = 3; j < n->kids.size(); ++j)
                bulkBm |= 1ULL << n->kids[j].first;
            BNode* bulkRoot = n->kids.size() > 3 ? n->kids[3].second : 0;
            pack_bits(rec, pos, bulkBm, 64);
            pack_bits(rec, pos, bulkRoot ? (uint64_t)bulkRoot->cell : 0, 22);
            pack_bits(rec, pos, bulkRoot ? (uint64_t)bulkRoot->stage : 0, 4);
            for (int j = 0; j < 3; ++j) {
                uint32_t rec32 = CHILD_ABSENT;
                if (j < 3 && j < (int)n->kids.size())
                    rec32 = pack_child(n->kids[j].first, n->kids[j].second->stage,
                                       n->kids[j].second->cell);
                pack_bits(rec, pos, rec32, 32);
            }
            pack_bits(rec, pos, 0, 7);
        } else {
            for (int j = 0; j < n->inln; ++j) {
                int len8 = 0;
                uint64_t frag = inline_frag(n->inl[j], n->origin, len8);
                pack_bits(rec, pos, frag, 64);
                pack_bits(rec, pos, (uint64_t)len8, 8);
                pack_bits(rec, pos, (uint64_t)n->inl[j].hop, 22);
            }
            if (n->type == 4) pack_bits(rec, pos, 0, 9);
            else pack_bits(rec, pos, 0, 43);
        }

        std::bitset<256>& row = out.banks[n->stage][n->cell >> 1];
        if (n->slot == 2) {
            row = rec;
        } else {
            int off = (n->cell & 1) << 7;
            for (int b = 0; b < 128; ++b) row.set(off + b, rec.test(b));
        }
    }

    // ---- roots and fronts ------------------------------------------------
    if (root0) {
        out.root.stage = root0->stage;
        out.root.cell = root0->cell;
    }
    int fi = 0;
    for (std::map<uint16_t, std::vector<BPrefix> >::iterator it = g16.begin();
         it != g16.end(); ++it, ++fi) {
        ImageFront e;
        e.key = it->first;
        e.loc.stage = r16[fi]->stage;
        e.loc.cell = r16[fi]->cell;
        out.front16.push_back(e);
    }
    fi = 0;
    for (std::map<uint64_t, std::vector<BPrefix> >::iterator it = g64.begin();
         it != g64.end(); ++it, ++fi) {
        ImageFront e;
        e.key = it->first;
        e.loc.stage = r64[fi]->stage;
        e.loc.cell = r64[fi]->cell;
        out.front64.push_back(e);
    }

    for (size_t i = 0; i < roots.size(); ++i) destroy(roots[i]);
    return out;
}
