#!/usr/bin/env python3
import json, os, random, subprocess, sys
sys.path.insert(0, '/workspace/tmp')
from refmodel import lpm, py_build, py_validate, mask, BMP_NULL, HOP_MAX

BINARY = '/workspace/tmp/scamptrie'
env = dict(os.environ, SCAMP_BINARY=BINARY)

def run_req(req):
    p = subprocess.run([sys.executable, '/workspace/run.py'], input=json.dumps(req).encode(),
                       capture_output=True, env=env, timeout=200)
    if p.returncode != 0:
        print(p.stdout.decode()[:2000], p.stderr.decode()[:2000])
        raise SystemExit('run failed')
    return json.loads(p.stdout)

def haddr(a): return f'{a:032x}'

class CaseGen:
    def __init__(self, rng):
        self.rng = rng
        self.live = {}          # (len, masked) -> hop
        self.saved = []         # list of dicts of routes
        self.loaded = {}        # loaded routes ({} = empty image)
        self.ops = []
        self.exp_answers = []
        self.exp_loads = []
        self.save_routes = []   # routes at each save (for snapshot validation)

    def put(self, a, ln, hop):
        self.ops.append(['put', haddr(a), ln, hop])
        self.live[(ln, mask(a, ln))] = hop

    def query(self, addrs):
        self.ops.append(['query', [haddr(a) for a in addrs]])
        for a in addrs:
            self.exp_answers.append(lpm(self.live, a))

    def image_query(self, addrs):
        self.ops.append(['image_query', [haddr(a) for a in addrs]])
        for a in addrs:
            self.exp_answers.append(lpm(self.loaded, a))

    def save(self):
        self.ops.append(['save'])
        self.saved.append(dict(self.live))
        self.save_routes.append(dict(self.live))

    def load_saved(self, idx):
        self.ops.append(['load_saved', idx])
        self.exp_loads.append(True)
        self.loaded = dict(self.saved[idx])

    def load(self, image, expect, routes=None):
        self.ops.append(['load', image])
        self.exp_loads.append(expect)
        if expect:
            assert routes is not None
            self.loaded = dict(routes)

def rand_addr(rng, guide=None):
    k = rng.random()
    if guide is not None and k < 0.5:
        # mutate a few bits of a guide address
        a = guide
        for _ in range(rng.randint(1, 3)):
            a ^= 1 << rng.randrange(128)
        return a
    if k < 0.15:
        return rng.randrange(1 << 128) & ~((1 << rng.choice([0, 8, 16, 32, 64, 96, 112, 120, 127])) - 1)
    return rng.randrange(1 << 128)

def gen_case(rng, nputs, nqueries, with_loads=True, tag=''):
    cg = CaseGen(rng)
    guides = []
    for _ in range(nputs):
        ln = rng.choice([rng.randrange(0, 129), rng.choice([0, 1, 8, 16, 17, 31, 32, 63, 64, 65, 96, 127, 128])])
        a = rand_addr(rng, rng.choice(guides) if guides and rng.random() < 0.6 else None)
        if rng.random() < 0.5 and guides:
            g = rng.choice(guides)
            ln2 = rng.choice([0, 1, 8, 16, 17, 32, 64, 65, 96, 128])
            a = mask(g, ln2) | (rand_addr(rng) & ((1 << (128 - ln2)) - 1))
            ln = ln2
        hop = rng.randrange(0, HOP_MAX + 1)
        cg.put(a, ln, hop)
        guides.append(a)
        r = rng.random()
        if r < 0.15:
            addrs = [rand_addr(rng, rng.choice(guides)) for _ in range(rng.randint(1, 3))]
            cg.query(addrs)
        elif r < 0.25:
            addrs = [rand_addr(rng, rng.choice(guides)) for _ in range(rng.randint(1, 3))]
            cg.image_query(addrs)
        elif r < 0.3:
            cg.save()
        elif r < 0.33 and cg.saved:
            cg.load_saved(rng.randrange(len(cg.saved)))
        elif r < 0.36 and with_loads:
            routes = dict(cg.live)
            img = py_build(routes, rng)
            cg.load(img, True, routes)
    # final checks
    if cg.saved:
        cg.load_saved(rng.randrange(len(cg.saved)))
    addrs = [rand_addr(rng, rng.choice(guides)) for _ in range(6)]
    cg.query(addrs)
    cg.image_query(addrs)
    return cg

def check_case(cg, result, tag):
    res = result
    if res['answers'] != cg.exp_answers:
        for i, (e, g) in enumerate(zip(cg.exp_answers, res['answers'])):
            if e != g:
                raise SystemExit(f'{tag}: answer mismatch at {i}: exp {e} got {g} (n={len(cg.exp_answers)})')
        raise SystemExit(f'{tag}: answer count mismatch')
    if res['loads'] != cg.exp_loads:
        raise SystemExit(f'{tag}: loads mismatch exp {cg.exp_loads} got {res["loads"]}')
    if len(res['snapshots']) != len(cg.save_routes):
        raise SystemExit(f'{tag}: snapshot count mismatch')
    for i, (img, routes) in enumerate(zip(res['snapshots'], cg.save_routes)):
        ok, got = py_validate(img)
        if not ok:
            raise SystemExit(f'{tag}: snapshot {i} fails independent validation')
        if got != routes:
            raise SystemExit(f'{tag}: snapshot {i} routes mismatch')
        # snapshot must be loadable and queryable via the C++ path too (done in phase 2)

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 20
    rng = random.Random(seed)
    for it in range(rounds):
        ncases = rng.choice([1, 2])
        cases = []
        cgs = []
        for c in range(ncases):
            nputs = rng.choice([3, 10, 40, 120])
            cg = gen_case(rng, nputs, 10)
            cases.append({'ops': cg.ops})
            cgs.append(cg)
        req = {'cases': cases}
        out = run_req(req)
        for c, cg in enumerate(cgs):
            check_case(cg, out['results'][c], f'seed{seed} it{it} case{c}')
        print(f'round {it} ok', flush=True)
    print('FUZZ OK')

main()
